def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    david_like_bid = None
    rich_aggressive = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if oid == 'David':
                    david_like_bid = float(bid)
            if opp.get('budget', 0) > 150 and opp.get('water_requirement', WATER_REQ) <= supply:
                if bid is not None and float(bid) >= 100:
                    rich_aggressive += 1

    if not alive:
        return max(0.0, min(budget, 20.0))

    capacity = int(supply // WATER_REQ)
    if capacity < 0:
        capacity = 0

    scarcity = 0.0
    if supply <= 16:
        scarcity = 1.0
    elif supply <= 19:
        scarcity = 0.7
    elif supply <= 22:
        scarcity = 0.4
    else:
        scarcity = 0.15

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    elif hp <= 6:
        urgency += 0.25

    if no_water_days >= 2:
        urgency += 0.9
    elif no_water_days == 1:
        urgency += 0.35

    if day >= 8:
        urgency += 0.2

    target = 0.0

    if david_like_bid is None:
        if prev_bids:
            david_like_bid = min(prev_bids)
        else:
            david_like_bid = 55.0

    if capacity >= 2:
        target = 34.0 + 12.0 * urgency + 6.0 * scarcity
    else:
        target = david_like_bid + 3.5 + 10.0 * urgency + 8.0 * scarcity

    if rich_aggressive >= 2 and hp > 4 and no_water_days == 0 and capacity < 2:
        target -= 10.0

    if hp <= 2 or no_water_days >= 2:
        target = max(target, 88.0)
    elif hp <= 4 or no_water_days == 1:
        target = max(target, 64.0)

    if budget < 90:
        target = min(target, budget * 0.72)
    elif budget < 160:
        target = min(target, budget * 0.6)
    else:
        target = min(target, budget * 0.42)

    floor_bid = 12.0 if capacity >= 2 else 28.0
    bid = max(floor_bid, target)
    bid = min(budget, bid)

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

